/**
 * parse_args().
 *
 * argparse works in two passes, and the split is observable. It first
 * classifies every token to build its option-string index, then consumes the
 * result. Ambiguous abbreviations are therefore reported during
 * classification, before any value is converted: `--a bogus --=5` complains
 * about the ambiguous `--=5`, not about `bogus`.
 *
 * Ordering matters at the end too — missing required options are reported
 * before unrecognized ones, so `-a 5 -b 5 -c A` (short flags that do not
 * exist) complains that --a/--b/--c are missing.
 */
parseArgs(argv) {
  const classified = this.classify(argv);

  const namespace = Object.create(null);
  for (const action of this.actions) {
    if (action.takesValue) namespace[action.dest] = null;
  }

  const seen = new Set();
  const extras = [];

  for (let i = 0; i < classified.length; i++) {
    const entry = classified[i];

    // Positionals and unrecognized options both become leftovers; this
    // parser declares no positional arguments.
    if (entry.kind === 'positional' || entry.action === null) {
      extras.push(entry.token);
      continue;
    }

    const { action, sep, explicitArg } = entry;

    if (action.action === 'help') {
      // A zero-argument action rejects a value attached with '=' rather than
      // discarding it, so `--help=x` and `-h=x` are errors. A value merely
      // concatenated to a short option (`-hx`) instead means bundled short
      // options, which argparse resolves by taking this action and then
      // re-dispatching '-' + the remainder. Help exits immediately, so that
      // continuation is unreachable here.
      if (explicitArg !== null && sep === '=') {
        this.error(
          `argument ${ArgumentParser.actionName(action)}: ignored explicit argument ${strRepr(explicitArg)}`,
        );
      }
      writeStdout(this.formatHelp());
      throw new SystemExit(0);
    }

    let raw;
    if (explicitArg !== null) {
      raw = explicitArg;
    } else if (i + 1 < classified.length && classified[i + 1].kind === 'positional') {
      raw = classified[i + 1].token;
      i++;
    } else {
      this.error(`argument ${ArgumentParser.actionName(action)}: expected one argument`);
    }

    namespace[action.dest] = this.convert(action, raw);
    seen.add(action.dest);
  }

  const missing = this.actions
    .filter((a) => a.required && !seen.has(a.dest))
    .map((a) => ArgumentParser.actionName(a));

  if (missing.length > 0) {
    this.error(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    this.error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return namespace;
}

